export default function config() {
  const spreadsheetId = "YOUR_SPREADSHEET_ID",
    sheetName = "Sheet1",
    now = new Date();
  if (!sheetName.trim()) throw Error("Set a worksheet name");
  return {
    spreadsheetId,
    sheetName,
    range: "'" + sheetName.replace(/'/g, "''") + "'",
    today: now.toISOString().slice(0, 10).replace(/-/g, "/"),
  };
}

