export default function plan({ values, today }) {
  if (!Array.isArray(values)) throw Error("Invalid sheet");
  if (values.length === 0) return { messages: [] };
  const headers = values[0];
  if (!Array.isArray(headers)) throw Error("Missing sheet headers");
  const names = ["ID", "Name", "Email", "Date", "Status", "Title", "Subject"],
    columns = {};
  for (const name of names) {
    const matches = headers.flatMap((x, i) => (x === name ? [i] : []));
    if (matches.length !== 1) throw Error("Each required header must occur exactly once");
    columns[name] = matches[0];
  }
  if (typeof today !== "string" || !/^\d{4}\/\d\d\/\d\d$/.test(today))
    throw Error("Invalid current date");
  const ids = new Map();
  for (const row of values.slice(1)) {
    if (!Array.isArray(row)) throw Error("Invalid sheet row");
    const id = row[columns.ID];
    if (id != null && String(id) !== "") ids.set(String(id), (ids.get(String(id)) ?? 0) + 1);
  }
  const messages = [];
  for (const row of values.slice(1)) {
    if (
      row[columns.Status] !== "Waiting for sending" ||
      row[columns.Date] !== today ||
      !["Name", "Email", "Date", "Title", "Subject"].every(
        (k) => row[columns[k]] != null && String(row[columns[k]]) !== "",
      )
    )
      continue;
    const id = row[columns.ID];
    if (id == null || String(id) === "" || ids.get(String(id)) !== 1)
      throw Error("Missing or duplicate message ID");
    messages.push(Object.fromEntries(names.map((k) => [k, String(row[columns[k]] ?? "")])));
  }
  return { messages };
}

