export default function match({ values, current, sheetName }) {
  if (
    !Array.isArray(values) ||
    !Array.isArray(values[0]) ||
    !current ||
    typeof current.ID !== "string"
  )
    throw Error("Invalid current message");
  const h = values[0],
    fields = ["ID", "Name", "Email", "Date", "Status", "Title", "Subject"],
    c = {};
  for (const k of fields) {
    const p = h.flatMap((x, i) => (x === k ? [i] : []));
    if (p.length !== 1) throw Error("Missing or duplicate required header");
    c[k] = p[0];
  }
  const found = values
    .slice(1)
    .flatMap((row, i) =>
      Array.isArray(row) && String(row[c.ID] ?? "") === current.ID ? [{ row, i }] : [],
    );
  if (found.length !== 1) throw Error("Message ID no longer uniquely identifies a row");
  const { row, i } = found[0];
  for (const k of fields)
    if (String(row[c[k]] ?? "") !== current[k]) throw Error("Message row changed after sending");
  let col = c.Status + 1,
    letters = "";
  while (col) {
    col--;
    letters = String.fromCharCode(65 + (col % 26)) + letters;
    col = Math.floor(col / 26);
  }
  if (typeof sheetName !== "string" || !sheetName.trim()) throw Error("Missing worksheet name");
  return {
    range: "'" + sheetName.replace(/'/g, "''") + "'!" + letters + (i + 2),
    values: [["Sent successfully"]],
  };
}

